let dt = Duration::from_nanos(16_666_667);
let mut prev = Instant::now();
let mut lag = Duration::ZERO;
while running(&world) {
    let now = Instant::now();
    lag += now - prev;                              // monotonic, non-decreasing
    prev = now;
    lag = lag.min(Duration::from_millis(250));      // clamp
    drain_input();
    while lag >= dt { world.step(dt); lag -= dt; }
    render(&world, lag.as_secs_f64() / dt.as_secs_f64());
    thread::sleep(Duration::from_millis(1));        // at-least; re-measured above
}

