impl ApplicationHandler for App {
    fn about_to_wait(&mut self, el: &ActiveEventLoop) {
        let now = Instant::now();
        self.lag += now - self.prev;
        self.prev = now;                                  // measured time
        self.lag = self.lag.min(Duration::from_millis(250));
        while self.lag >= DT { self.world.step(DT); self.lag -= DT; }
        self.window.request_redraw();
        el.set_control_flow(ControlFlow::WaitUntil(now + DT - self.lag));
    }
}
